const err = $input.first().json || {};
if ($env.MONGODB_URI) {
  try {
    const { MongoClient } = require('mongodb');
    const c = new MongoClient($env.MONGODB_URI);
    await c.connect();
    await c.db($env.MONGODB_DB || 'tradesejon_prod').collection('audit_logs').insertOne({ ...err, severity: 'error', timestamp: new Date() });
    await c.close();
  } catch (e) {}
}
const ceoChat = String($env.CEO_USER_IDS || '').split(',')[0].trim();
const botTok = $env.TELEGRAM_CEO_BOT_TOKEN || '';
if (ceoChat && botTok) {
  await fetch(`https://api.telegram.org/bot${botTok}/sendMessage`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: ceoChat, text: `🚨 <b>Workflow Error Alert:</b> ${err.workflow}\n<code>${err.message}</code>`, parse_mode: 'HTML' })
  }).catch(() => null);
}
return [{ json: { ok: true, alerted: true } }];
